AssistantMessageToolRequest(name='create', tool_call_id='function-call-da1711ea-43bc-4263-9b00-e3c2295b95db', arguments={'file_text': 'const { useState } = React;

const RadioOption = ({ id, name, value, label, checked, onChange }) => {
    return (
        <label htmlFor={id} className="radio-option">
            <input
                type="radio"
                id={id}
                name={name}
                value={value}
                checked={checked}
                onChange={onChange}
                required
            />
            <span className="radio-label">{label}</span>
        </label>
    );
};

const NotificationForm = () => {
    const [preference, setPreference] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (e) => {
        e.preventDefault();
        if (preference) {
            setSubmitted(true);
            // In a real app, you'd send this to an API
            console.log('Submitted preference:', preference);
        }
    };

    const options = [
        { id: 'email', value: 'Email', label: 'Email' },
        { id: 'sms', value: 'SMS', label: 'SMS' },
        { id: 'push', value: 'Push Notifications', label: 'Push Notifications' }
    ];

    if (submitted) {
        return (
            <div className="card" role="status" aria-live="polite">
                <h1>Thank you!</h1>
                <p>Your notification preference has been saved as: <strong>{preference}</strong></p>
                <div className="success-message">Settings updated successfully</div>
                <button 
                    className="submit-button" 
                    style={{ marginTop: '1rem' }}
                    onClick={() => setSubmitted(false)}
                >
                    Back to form
                </button>
            </div>
        );
    }

    return (
        <div className="container">
            <form className="card" onSubmit={handleSubmit}>
                <h1>Settings</h1>

                <div className="form-field">
                    <fieldset>
                        <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
                        <div className="radio-group">
                            {options.map(option => (
                                <RadioOption
                                    key={option.id}
                                    id={option.id}
                                    name="notification-preference"
                                    value={option.value}
                                    label={option.label}
                                    checked={preference === option.value}
                                    onChange={(e) => setPreference(e.target.value)}
                                />
                            ))}
                        </div>
                    </fieldset>
                </div>

                <button type="submit" className="submit-button">
                    Save Preferences
                </button>
            </form>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<NotificationForm />);
